def is_balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


for text in ["(a[1] + b)", "{[}]", "((x)", "f(g[h{}])"]:
    result = "balanced" if is_balanced(text) else "not balanced"
    print(f"{text}: {result}")

