temps = [30, 32, 31, 29, 35, 33, 34, 28]
wait = [0] * len(temps)
stack = []
for i, t in enumerate(temps):
    while stack and temps[stack[-1]] < t:
        j = stack.pop()
        wait[j] = i - j
    stack.append(i)

for i in range(len(temps)):
    if wait[i]:
        print(f"Day {i + 1} ({temps[i]}): warmer in {wait[i]}")
    else:
        print(f"Day {i + 1} ({temps[i]}): none warmer")

from collections import deque

visits = [12, 30, 25, 8, 40, 15, 9, 22]
k = 3
dq = deque()
for i, x in enumerate(visits):
    while dq and visits[dq[-1]] <= x:
        dq.pop()
    dq.append(i)
    if dq[0] <= i - k:
        dq.popleft()
    if i >= k - 1:
        window = visits[i - k + 1:i + 1]
        print(f"{window}: peak {visits[dq[0]]}")

import heapq

k = 3
top = []
for score in [40, 85, 60, 72, 91, 55, 88]:
    if len(top) < k:
        heapq.heappush(top, score)
    else:
        heapq.heappushpop(top, score)
    if len(top) == k:
        print(f"{score}: 3rd best is {top[0]}")
    else:
        print(f"{score}: fewer than 3 scores")

print("Top 3:", sorted(top, reverse=True))
